(async () => {
   const { fadeFinder } = await import('/systems/fantastic-depths/module/fantastic-depths.min.js');

   let tier = null;
   try {
      const choice = await foundry.applications.api.DialogV2.prompt({
         window: { title: 'Magic Scrolls' },
         content: '<p style="margin:0 0 0.5rem;">Select the treasure tier to determine the scroll modifier (+0, +6, or +12).</p><div style="display:flex;align-items:center;gap:1rem;padding:0.25rem 0 0.5rem;"><label style="display:flex;align-items:center;gap:0.3rem;margin:0;cursor:pointer;"><input type="radio" name="tier" value="minor" checked style="margin:0;width:auto;flex:none;"> Minor (+0)</label><label style="display:flex;align-items:center;gap:0.3rem;margin:0;cursor:pointer;"><input type="radio" name="tier" value="medium" style="margin:0;width:auto;flex:none;"> Medium (+6)</label><label style="display:flex;align-items:center;gap:0.3rem;margin:0;cursor:pointer;"><input type="radio" name="tier" value="major" style="margin:0;width:auto;flex:none;"> Major (+12)</label></div>',
         ok: {
            label: 'Roll',
            callback: (event, button) => button.form.elements.tier.value
         }
      });
      tier = { minor: 0, medium: 6, major: 12 }[choice] ?? null;
   } catch (err) {
      tier = null;
   }
   if (tier === null) return;

   const base = await new Roll('1d8').roll();
   const total = base.total + tier;

   const rows = {
      1: { count: 1, level: '1' },
      2: { count: 1, level: '1d3' },
      3: { count: 2, level: '1d2' },
      4: { count: 3, level: '1' },
      5: { cursed: true },
      6: { protection: 1 },
      7: { protection: 1 },
      8: { count: 2, level: '1d4' },
      9: { count: 2, level: '1d6' },
      10: { count: 1, level: '1d4+2' },
      11: { count: 5, level: '1d3' },
      12: { cursed: true },
      13: { protection: 2 },
      14: { protection: 2 },
      15: { count: 5, level: '1d6' },
      16: { count: 6, level: '1d6' },
      17: { count: 7, level: '1d6' },
      18: { count: 8, level: '1d6' },
      19: { cursed: true },
      20: { protection: 3 }
   };
   const row = rows[total];
   if (!row) return;

   const mult = ['', ' (normal duration)', ' (double duration)', ' (triple duration & effects)'];
   const lines = [
      '<div class="text-size16"><strong>Magic Scrolls</strong></div>',
      `<p>Roll: ${base.result} + ${tier} = <strong>${total}</strong></p><hr/>`
   ];

   const pack = game.packs.get('fade-white-box-fmag.items');

   if (row.protection) {
      const table = await fadeFinder.getRollTable('Protection Scrolls');
      if (!table) {
         ui.notifications.error('Protection Scrolls roll table not found.');
         return;
      }
      const draw = await table.draw({ displayChat: false });
      const protHtml = (draw.results[0]?.text ?? '').replace(/^<p>(.*)<\/p>\s*$/s, '$1');
      lines.push(`<p><strong>Protection Scroll${mult[row.protection]}</strong>: ${protHtml}</p>`);
   } else if (row.cursed) {
      const items = await pack.getDocuments();
      const cursed = items.find(i => i.name === 'Cursed Scroll');
      if (cursed) lines.push(`<p><strong>Cursed Scroll</strong>: @UUID[${cursed.uuid}]{Cursed Scroll}</p>`);
      else lines.push('<p><strong>Cursed Scroll</strong> (no item found)</p>');
   } else {
      lines.push(`<p><strong>${row.count} scroll(s), level ${row.level}</strong></p>`);
      const items = await pack.getDocuments();
      const muByLevel = {};
      const clByLevel = {};
      for (const s of items) {
         if (s.type !== 'item' || !/^Scroll of /.test(s.name)) continue;
         const uuid = s.system?.spells?.[0]?.uuid;
         if (!uuid) continue;
         const spell = await fromUuid(uuid);
         if (!spell) continue;
         const lvl = spell.system?.spellLevel;
         if (lvl == null) continue;
         const classes = (spell.system?.classes || []).map(c => c.name);
         if (classes.includes('Magic-User')) (muByLevel[lvl] ??= []).push(s);
         if (classes.includes('Cleric')) (clByLevel[lvl] ??= []).push(s);
      }
      for (let i = 0; i < row.count; i++) {
         const typeRoll = await new Roll('1d6').roll();
         const isMU = typeRoll.total <= 3;
         const clsName = isMU ? 'Magic-User' : 'Cleric';
         let level = (await new Roll(row.level).roll()).total;
         while (!isMU && level === 6) level = (await new Roll(row.level).roll()).total;
         const bucket = isMU ? muByLevel[level] : clByLevel[level];
         if (!bucket?.length) {
            lines.push(`<p>${i + 1}. <em>${clsName} level ${level}</em>: no scroll item found.</p>`);
            continue;
         }
         const item = bucket[Math.floor(Math.random() * bucket.length)];
         lines.push(`<p>${i + 1}. <em>${clsName} level ${level}</em>: @UUID[${item.uuid}]{${item.name}}</p>`);
      }
   }

   const chatMsgData = { content: lines.join(''), speaker: ChatMessage.getSpeaker() };
   ChatMessage.create(chatMsgData);
})();
